"""mypy on server/, blocking only on a finding that is not in the baseline.

14/11 ("everything free that helps"): server/ had never been type-checked. The first
run found 591 errors -- too many to fix before checking anything, and a check
that is red forever is a check everybody learns to ignore. So the existing ones
are the baseline, and only a NEW one is red.

    python .github/typecheck/mypy_gate.py check  [--baseline FILE] [--min-files N] [--advisory-until DATE] [PATHS...]
    python .github/typecheck/mypy_gate.py update [--baseline FILE] [PATHS...]

A finding is `file <TAB> code <TAB> message`, WITHOUT the line number: an edit
above an old finding must not make it new. The baseline counts each key, so a
second copy of a known error in the same file is new.

check: exit 0 -- nothing new (a key whose count went down is reported: shrink
the baseline with `update`); 1 -- a new finding; 2 -- mypy did not run or did not
say how many files it checked (principle 5: "no error" from a run that checked
nothing is not a pass), or checked fewer than --min-files.

--advisory-until DATE (owner, 15/11, #2810 item 7: "the first two weeks, without
failing a merge"): until that day (UTC) a NEW finding is still reported -- a
warning annotation, the summary, the log -- but exits 0 instead of 1. It softens
only 1: a run that could not verify (2) fails inside the grace period too, because
"nothing found" from a run that did not run is not advisory, it is unknown. On and
after DATE the same finding is red; no one has to remember to flip anything.
"""

from __future__ import annotations

import argparse
import datetime
import os
import re
import subprocess
import sys
from collections import Counter
from pathlib import Path

HERE = Path(__file__).resolve().parent
BASELINE = HERE / "mypy-baseline.txt"
#: the flags are part of the baseline: change them and the baseline is regenerated
FLAGS = ["--python-version", "3.13", "--ignore-missing-imports", "--show-error-codes",
         "--no-pretty", "--no-color-output", "--hide-error-context"]
ERROR = re.compile(r"^(?P<file>[^:]+):(?P<line>\d+): error: (?P<msg>.*?)  \[(?P<code>[a-z0-9-]+)\]$")
CHECKED = re.compile(r"(?:Found \d+ errors? in \d+ files? \(checked (\d+) source files?\)"
                     r"|Success: no issues found in (\d+) source files?)")


def today() -> datetime.date:
    """UTC, so the runner's time zone does not move the day the grace period ends."""
    return datetime.datetime.now(datetime.timezone.utc).date()


def run_mypy(paths: list[str]) -> tuple[int, str]:
    proc = subprocess.run([sys.executable, "-m", "mypy", *FLAGS, *paths], capture_output=True,
                          text=True, stdin=subprocess.DEVNULL)
    return proc.returncode, proc.stdout + proc.stderr


def parse(output: str) -> tuple[Counter, dict[tuple[str, str, str], list[str]], int | None]:
    keys: Counter = Counter()
    where: dict[tuple[str, str, str], list[str]] = {}
    checked = None
    for line in output.splitlines():
        m = ERROR.match(line)
        if m:
            key = (Path(m["file"]).as_posix(), m["code"], m["msg"])
            keys[key] += 1
            where.setdefault(key, []).append(f"{Path(m['file']).as_posix()}:{m['line']}")
        c = CHECKED.search(line)
        if c:
            checked = int(c.group(1) or c.group(2))
    return keys, where, checked


def load(path: Path) -> Counter:
    keys: Counter = Counter()
    for line in path.read_text(encoding="utf-8").splitlines():
        if line.startswith("#") or not line.strip():
            continue
        count, file, code, msg = line.split("\t", 3)
        keys[(file, code, msg)] = int(count)
    return keys


def save(path: Path, keys: Counter) -> None:
    head = ("# mypy findings on server/ that existed before the gate (14/11). Generated by\n"
            "# `python .github/typecheck/mypy_gate.py update` -- do not edit by hand.\n"
            "# count <TAB> file <TAB> code <TAB> message\n")
    rows = [f"{n}\t{f}\t{c}\t{m}" for (f, c, m), n in sorted(keys.items())]
    path.write_text(head + "\n".join(rows) + "\n", encoding="utf-8", newline="\n")


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n", 1)[0])
    ap.add_argument("mode", choices=["check", "update"])
    ap.add_argument("paths", nargs="*", default=["server"])
    ap.add_argument("--baseline", type=Path, default=BASELINE)
    ap.add_argument("--min-files", type=int, default=1)
    ap.add_argument("--advisory-until", type=datetime.date.fromisoformat, default=None, metavar="DATE",
                    help="YYYY-MM-DD: a new finding is reported but exits 0 before this day (UTC)")
    a = ap.parse_args(argv)
    rc, out = run_mypy(a.paths)
    keys, where, checked = parse(out)
    if rc not in (0, 1) or checked is None:
        print(out[-3000:])
        print(f"mypy-gate: CANNOT VERIFY -- mypy exit {rc}, files checked: {checked}")
        return 2
    if checked < a.min_files:
        print(f"mypy-gate: CANNOT VERIFY -- mypy checked {checked} files, fewer than {a.min_files}")
        return 2
    if a.mode == "update":
        save(a.baseline, keys)
        print(f"mypy-gate: baseline written, {sum(keys.values())} findings in {checked} files")
        return 0
    base = load(a.baseline)
    new = {k: n - base[k] for k, n in keys.items() if n > base[k]}
    fewer = {k: base[k] - keys[k] for k in base if keys[k] < base[k]}
    lines = [f"## mypy on server/ -- {sum(keys.values())} findings in {checked} files, "
             f"{sum(new.values())} new, {sum(fewer.values())} fixed", ""]
    for (f, c, m), n in sorted(new.items()):
        lines.append(f"- NEW ({n}) `{f}` [{c}] {m} -- at {', '.join(where[(f, c, m)])}")
    if fewer:
        lines.append(f"- {len(fewer)} baseline keys went down: run `mypy_gate.py update` to shrink the baseline")
    advisory = bool(new) and a.advisory_until is not None and today() < a.advisory_until
    if advisory:
        lines.append(f"- ADVISORY until {a.advisory_until}: {sum(new.values())} new finding(s) reported, not failing; "
                     "from that day the same run is red")
    text = "\n".join(lines) + "\n"
    print(text)
    if advisory:
        print(f"::warning::mypy-gate: {sum(new.values())} new finding(s), advisory until {a.advisory_until} (UTC)")
    summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary:
        with open(summary, "a", encoding="utf-8") as fh:
            fh.write(text)
    return 1 if new and not advisory else 0


if __name__ == "__main__":
    sys.exit(main())
